<?php
declare(strict_types=1);

// Rebuilds ../callsign-data.php from ../vatsim.sqlite (VATSpy airports/FIRs)
// and tools/vnas_facilities.json (VATUSA vNAS facility tree, one entry per ARTCC).
//
//   php tools/build-callsign-data.php
//
// The generated file is a plain PHP array, so the website no longer needs
// pdo_sqlite at runtime.

$root = dirname(__DIR__);
$db = new PDO('sqlite:' . $root . '/vatsim.sqlite');
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

$airports = [];
$iataCandidates = [];
foreach ($db->query('SELECT icao, iata, fir FROM airports ORDER BY icao') as $row) {
    $icao = strtoupper(trim((string)$row['icao']));
    $fir = strtoupper(trim((string)$row['fir']));
    if ($icao === '') continue;
    $airports[$icao] = $fir;
    $iata = strtoupper(trim((string)$row['iata']));
    if ($iata !== '' && preg_match('/^[A-Z0-9]{3}$/', $iata)) $iataCandidates[$iata][] = $icao;
}

// IATA / FAA identifiers: used for callsigns such as HNL_TWR, ANC_GND, YYZ_TWR.
// When an identifier is shared, prefer US (K/P), then Canada, then the first.
$iata = [];
foreach ($iataCandidates as $code => $icaos) {
    usort($icaos, function ($a, $b) {
        $rank = fn($x) => ($x[0] === 'K' ? 0 : ($x[0] === 'P' ? 1 : ($x[0] === 'C' ? 2 : 3)));
        return $rank($a) <=> $rank($b) ?: strcmp($a, $b);
    });
    $iata[$code] = $icaos[0];
}

$firNames = [];
$firPrefixes = [];
foreach ($db->query('SELECT code, name, prefix FROM firs ORDER BY code') as $row) {
    $code = strtoupper(trim((string)$row['code']));
    $firNames[$code] = (string)$row['name'];
    $prefix = strtoupper(trim((string)$row['prefix']));
    // Blank prefix = the FIR's callsigns use the FIR code itself.
    $firPrefixes[$prefix !== '' ? $prefix : $code] ??= $code;
    $firPrefixes[$code] ??= $code;
}
// FIR codes that only exist on airports (e.g. ZSHA, ZBPE) are valid FIR callsign prefixes too.
foreach (array_unique(array_values($airports)) as $code) if ($code !== '') $firPrefixes[$code] ??= $code;

// vNAS: every facility id (ARTCC/TRACON/ATCT) and every position callsign prefix -> ARTCC.
$vnas = json_decode((string)file_get_contents(__DIR__ . '/vnas_facilities.json'), true, 512, JSON_THROW_ON_ERROR);
$us = [];
foreach ($vnas as $artcc => $entry) {
    foreach (preg_split('/\s+/', trim($entry['f'])) as $token) $us[explode(':', $token)[0]] = $artcc;
}
foreach ($vnas as $artcc => $entry) {
    foreach (preg_split('/\s+/', trim($entry['p'])) as $prefix) {
        if (isset($vnas[$prefix]) && $prefix !== $artcc) continue; // neighbour ARTCC reference
        $us[$prefix] ??= $artcc;
    }
}
ksort($us);

$data = ['airports' => $airports, 'iata' => $iata, 'firNames' => $firNames, 'firPrefixes' => $firPrefixes, 'us' => $us];
$out = "<?php\n// Generated by tools/build-callsign-data.php from vatsim.sqlite (VATSpy) and tools/vnas_facilities.json (vNAS).\n// Do not edit by hand.\nreturn " . var_export($data, true) . ";\n";
$out = preg_replace(['/=> \n\s+array \(/', '/^[ \t]+/m'], ['=> array (', ''], $out);
file_put_contents($root . '/callsign-data.php', $out);
printf("airports=%d iata=%d firs=%d firPrefixes=%d us=%d\n", count($airports), count($iata), count($firNames), count($firPrefixes), count($us));
